def align_company_taxonomy(apps, schema_editor):
    Company = apps.get_model('tenancy', 'Company')
    Property = apps.get_model('real_estate', 'Property')
    Candidate = apps.get_model('real_estate', 'PropertyCandidate')
    PropertyType = apps.get_model('real_estate', 'PropertyType')
    company_ids = set(Company.objects.filter(industry_type='real_estate').values_list('id', flat=True))
    company_ids.update(Company.objects.filter(company_type='control').values_list('id', flat=True))
    company_ids.update(PropertyType.objects.values_list('company_id', flat=True))

    for company_id in company_ids:
        for legacy_code, target_code in (('retail', 'shop'), ('land', 'plot')):
            legacy = PropertyType.objects.filter(company_id=company_id, code=legacy_code).first()
            target = PropertyType.objects.filter(company_id=company_id, code=target_code).first()
            if legacy and target:
                Property.objects.filter(property_type_id=legacy.pk).update(property_type_id=target.pk)
                Candidate.objects.filter(property_type_id=legacy.pk).update(property_type_id=target.pk)
                legacy.delete()
            elif legacy:
                legacy.code = target_code
                legacy.save(update_fields=['code'])

        for order, (code, name, category, aliases) in enumerate(CANONICAL_TYPES, start=1):
            record, _ = PropertyType.objects.get_or_create(
                company_id=company_id,
                code=code,
                defaults={
                    'name': name,
                    'category': category,
                    'sort_order': order * 10,
                    'aliases': aliases,
                },
            )
            updates = {}
            name_available = not PropertyType.objects.filter(
                company_id=company_id, name=name,
            ).exclude(pk=record.pk).exists()
            if record.name != name and name_available:
                updates['name'] = name
            if record.category != category:
                updates['category'] = category
            merged_aliases = list(dict.fromkeys([*(record.aliases or []), *aliases]))
            if merged_aliases != record.aliases:
                updates['aliases'] = merged_aliases
            if updates:
                PropertyType.objects.filter(pk=record.pk).update(**updates)


